  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C83", "C75", "C90", "C79", "C104"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C83"],
  "claims": [
    {
      "claim": "C83 reports that pirazolac, an acidic 1-aryl-3,5-diaryl pyrazole carboxylate sharing the query's azole-carboxylate-diaryl framework, had complete systemic availability in humans (oral/IV AUC ratio f = 0.88–0.99), directly supporting F >= 20% for this structural class.",
      "card_ids": ["C83"]
    },
    {
      "claim": "Oral exposure records for related acidic/phenolic heteroaromatics show measurable human plasma concentrations after oral dosing (eltrombopag 100 mg Cmax 11.1 µg/mL; rhein Cmax 2.5–4.7 mg/L after 50–100 mg diacerein), consistent with absorption of this polarity class, although no F is reported.",
      "card_ids": ["C75", "C90", "C79", "C104"]
    },
    {
      "claim": "Exposure-only L3 records for other reference molecules (e.g., meloxicam, mesalamine, aspirin) report Cmax/AUC without IV comparators and are neutral for the F >= 20% threshold; they do not constitute low-F evidence.",
      "card_ids": ["C78", "C64", "C73"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C83", "C75", "C90", "C79", "C104"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No query-specific permeability, metabolism, or first-pass data.",
    "Most L3 exposure records lack IV comparators and therefore cannot yield F values.",
    "Transferability of the pirazolac high-F result is limited by structural differences (pyrazole vs triazole, halogens vs ortho-phenols, acetic acid vs benzoic acid)."
  ],
  "decision_summary": "L3 adds one direct high-F comparator (pirazolac, f = 0.88–0.99 in humans) with a similar acidic azole-diaryl carboxylate scaffold, plus measurable oral exposure for related acid/phenol heteroaromatics; no transferable low-F evidence appears. The prior high prediction is therefore strengthened to moderate confidence."
}

